import { useEffect, useRef, useState } from "react";
import { Animated, Easing, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface HoldToConfirmProps {
  label: string;
  confirmedLabel?: string;
  onConfirm: () => void;
  /** Milliseconds the press must last. */
  duration?: number;
  tone?: "accent" | "danger" | "neutral";
  confirmed?: boolean;
  onHoldChange?: (holding: boolean) => void;
  disabled?: boolean;
  /** Extend the inner, named parts of the button: fill or label. The React Native counterpart of `classNames`. */
  styles?: {
    root?: StyleProp<ViewStyle>;
    fill?: StyleProp<ViewStyle>;
    label?: StyleProp<TextStyle>;
  };
}

/** Press and hold; a fill sweeps across, and the action fires only when it completes. Letting go early rewinds it. */
export function HoldToConfirm({ label, confirmedLabel = "Done", onConfirm, duration = 1200, tone = "accent", confirmed, onHoldChange, disabled, styles: parts }: HoldToConfirmProps) {
  const tokens = useTokens();
  const [progress] = useState(() => new Animated.Value(0));
  const [done, setDone] = useState(false);
  const holding = useRef(false);
  const finished = confirmed ?? done;
  const color = tone === "danger" ? tokens.danger : tone === "neutral" ? tokens.textSecondary : tokens.accent;

  // A controlled `confirmed` of false rewinds the fill; the internal flag is ignored while the prop is given.
  useEffect(() => {
    if (confirmed === false) progress.setValue(0);
  }, [confirmed, progress]);

  function start() {
    if (disabled || finished) return;
    holding.current = true;
    onHoldChange?.(true);
    Animated.timing(progress, { toValue: 1, duration, easing: Easing.linear, useNativeDriver: false }).start(({ finished: complete }) => {
      if (!complete || !holding.current) return;
      holding.current = false;
      setDone(true);
      onHoldChange?.(false);
      onConfirm();
    });
  }

  function cancel() {
    if (!holding.current) return;
    holding.current = false;
    onHoldChange?.(false);
    Animated.timing(progress, { toValue: 0, duration: 220, useNativeDriver: false }).start();
  }

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={finished ? confirmedLabel : `${label}, press and hold`}
      accessibilityState={{ disabled: Boolean(disabled) }}
      disabled={disabled}
      onPressIn={start}
      onPressOut={cancel}
      style={[local.root, { minHeight: metrics.controlHeight.md, borderColor: finished ? color : tokens.border, backgroundColor: tokens.surface, opacity: disabled ? 0.52 : 1 }, parts?.root]}
    >
      <Animated.View
        pointerEvents="none"
        style={[StyleSheet.absoluteFill, { width: progress.interpolate({ inputRange: [0, 1], outputRange: ["0%", "100%"] }), backgroundColor: `${color}26` }, parts?.fill]}
      />
      <View style={local.content}>
        <Text style={[{ color: finished ? color : tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.label]}>{finished ? confirmedLabel : label}</Text>
      </View>
    </Pressable>
  );
}

const local = StyleSheet.create({
  root: { alignSelf: "flex-start", overflow: "hidden", borderWidth: 1, borderRadius: metrics.radiusControl, paddingHorizontal: metrics.space[4], justifyContent: "center" },
  content: { alignItems: "center", justifyContent: "center" },
});

export default HoldToConfirm;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
